final class ConnectionMockHelper {
    private ConnectionMockHelper() {
    }

    static void mockPrepareStatement(Connection connection, PreparedStatement preparedStatement) throws SQLException {
        when(connection.prepareStatement(anyString())).thenReturn(preparedStatement);
    }
}
